"""This file contains the Volume View Registration Page Object class for the VolumeView Registration window in XVI"""

import logging
from .. interactions import VolumeViewRegFuncs
from interops.libraries.desktop import AutManager
from interops.libraries.xvi import XviAutController
from interops.libraries.squish_actions.constants import XVI_APP_NAME, XVI_REGISTRATION_APP_NAME
from typing import Dict

logger = logging.getLogger(__name__)

class VolumeViewRegistration():

    def __init__(self, host_address="192.168.30.4") -> None:
        # Check if squish has already attached to XVI SRI app, if not attach to it
        if not AutManager.is_aut_running(XVI_APP_NAME):
            xvi_sri_driver = XviAutController.xvi_aut(serverAddress=host_address, serverPort=4322)
            xvi_sri_driver.attach_to_aut(kill_existing_process=True)

        """
        TODO JC - revisit this. Attach to default SRI AUT or XVI3 (Registration window) AUT when this page object is created?
        Depends on when this page object is created in the test script and whether the
        registration window is already open in the workflow. Using the ready() function will
        ensure that Squish attaches to the xvi3 AUT instead if the Registration objects whilst
        attached to the main SRI AUT fail to get recognised.
        """
        # if not AutManager.is_aut_running(XVI_REGISTRATION_APP_NAME):
        #     xvi_sri_driver = XviAutController.xvi_registration_aut(serverAddress=host_address, serverPort=4322)
        #     xvi_sri_driver.attach_to_aut(kill_existing_process=True)
        self.xvi_host_address = host_address

    def __attach_to_registration_window(self, aut_attach_retries: int = 2) -> None:
        '''
        Ataches to the Volume View Registration Window directly. Squish recognises this window as a separate
        AUT and the window object is not recognized as part of the main SRI AUT.
        '''
        try:
            xvi_vol_view_reg_driver = XviAutController.xvi_registration_aut(serverAddress=self.xvi_host_address, serverPort=4322)
            # There should already be an existing startwinaut process for the main SRI AUT so leave this running and launch a new
            # instance of the startwinaut process for the xvi3 AUT.
            for i in range(aut_attach_retries):
                try:
                    print(f"xvi3 attach attempt no. {i+1}")
                    self.xvi3_volumeview_driver = xvi_vol_view_reg_driver.attach_to_aut(launch_new_startwinaut=True, get_running_aut_pid_retries=200)
                except Exception as e:
                    logger.info(f"Failed to attach to VolumeView Registration window on attempt no: {i+1}. Error: {e}.")
        except Exception as e:
            logger.info(f"Unable to attach to Volume View Registration Window directly. Error: {e} ")

    def ready(self, wait_timeout=3000, retries: int=2) -> bool:
        '''
        Waits for the VolumeView Registration window to be ready.

        Returns:
            bool - True if VolumeView Registration window is ready, False otherwise
        '''
        for i in range(retries):
            try:
                return VolumeViewRegFuncs.wait_for_volume_view_reconstruction_pane(wait_timeout)
            except Exception as e:
                logger.info(f"VolumeView Registration window failed to open or was not recognised on attempt no: {i+1}.\
                    Error: {e}. Try attaching directly to the Registration window ('xvi3' AUT) instead of the main SRI AUT")
                self.__attach_to_registration_window()
        return False

    def toggle_reference_clipbox_checkbox(self, enable_checkbox: bool=True) -> None:
        '''
        Toggles the Clipbox checkbox in the Reference Pane to either checked
        or unchecked

        Args:
            enable_checkbox (bool): True to check checkbox, False to uncheck
        '''
        if enable_checkbox:
            VolumeViewRegFuncs.check_volume_view_registration_reference_clipbox_checkbox()
        else:
            VolumeViewRegFuncs.uncheck_volume_view_registration_reference_clipbox_checkbox()

    def toggle_reference_cor_ref_checkbox(self, enable_checkbox: bool=True) -> None:
        '''
        Toggles the Cor Ref checkbox in the Reference Pane to either checked
        or unchecked

        Args:
            enable_checkbox (bool): True to check checkbox, False to uncheck
        '''
        if enable_checkbox:
            VolumeViewRegFuncs.check_volume_view_registration_reference_cor_ref_checkbox()
        else:
            VolumeViewRegFuncs.uncheck_volume_view_registration_reference_cor_ref_checkbox()

    def toggle_reference_clipbox_locked_context_menu_item(self, enable_checkbox: bool=True) -> None:
        '''
        Toggles the Clipbox Locked context menu item in the Reference Pane to either checked
        or unchecked

        Args:
            enable_checkbox (bool): True to check checkbox, False to uncheck
        '''
        if enable_checkbox:
            VolumeViewRegFuncs.check_volume_view_registration_reference_clipbox_locked_context_menu_item()
        else:
            VolumeViewRegFuncs.uncheck_volume_view_registration_reference_clipbox_locked_context_menu_item()

    def get_current_registration_method(self) -> str:
        '''
        Gets the current registration method text from the VolumeView Registration Method ComboBox

        Returns:
            str - Registration method text
        '''
        return VolumeViewRegFuncs.get_current_volume_view_registration_method_from_combobox()

    def select_registration_method_combobox_option(self, reg_method: str) -> None:
        '''
        Select one of the methods from the registration (clipbox) method combobox
        for the given method string

        Args:
            reg_method (str): Name of the registration method to select from the combobox

            reg_method can be one of the following strings:
            "Manual", "Bone (T+R)", "Seed (T+R)", "Seed (T)", "Grey Value (T+R)" or
            "Grey Value (T)"
        '''
        if reg_method.casefold() == "Manual".casefold():
            VolumeViewRegFuncs.select_volume_view_registration_method_manual()
        elif reg_method.casefold() == "Bone (T+R)".casefold():
            VolumeViewRegFuncs.select_volume_view_registration_method_bone_t_and_r()
        elif reg_method.casefold() == "Seed (T+R)".casefold():
            VolumeViewRegFuncs.select_volume_view_registration_method_seed_t_and_r()
        elif reg_method.casefold() == "Seed (T)".casefold():
            VolumeViewRegFuncs.select_volume_view_registration_method_seed_t()
        elif reg_method.casefold() == "Grey Value (T+R)".casefold():
            VolumeViewRegFuncs.select_volume_view_registration_method_grey_t_and_r()
        elif reg_method.casefold() == "Grey Value (T)".casefold():
            VolumeViewRegFuncs.select_volume_view_registration_method_grey_t()
        else:
            logger.info(f"Invalid Registration method: {reg_method}, unable to set")

    def set_registration_rotation_field_values(self, position_value_pairs: Dict[str, str]) -> None:
        '''
        Modifies one or more Registration Rotation fields as specified in the dictionary arg
        of position field key: set value pairs

        Args:
            setting_type_value_pairs (dict of str: str): Dictionary of position field
            to set string as the key, and string value to set as the value.

            Position Field Keys can be one of the following strings:
            "X", "Y", "Z"

            Value can be a numeric value as a string
        '''
        for key, value in position_value_pairs.items():
            if key.casefold() == "X".casefold():
                VolumeViewRegFuncs.edit_volume_view_registration_rotation_x_textfield(value)
            elif key.casefold() == "Y".casefold():
                VolumeViewRegFuncs.edit_volume_view_registration_rotation_y_textfield(value)
            elif key.casefold() == "Z".casefold():
                VolumeViewRegFuncs.edit_volume_view_registration_rotation_z_textfield(value)
            else:
                logger.info(f"Invalid position field: {key}, unable to set")

    def set_registration_translation_field_values(self, position_value_pairs: Dict[str, str]) -> None:
        '''
        Modifies one or more Registration Translation fields as specified in the dictionary arg
        of position field key: set value pairs

        Args:
            setting_type_value_pairs (dict of str: str): Dictionary of position field
            to set string as the key, and string value to set as the value.

            Position Field Keys can be one of the following strings:
            "X", "Y", "Z"

            Value can be a numeric value as a string
        '''
        for key, value in position_value_pairs.items():
            if key.casefold() == "X".casefold():
                VolumeViewRegFuncs.edit_volume_view_registration_translation_x_textfield(value)
            elif key.casefold() == "Y".casefold():
                VolumeViewRegFuncs.edit_volume_view_registration_translation_y_textfield(value)
            elif key.casefold() == "Z".casefold():
                VolumeViewRegFuncs.edit_volume_view_registration_translation_z_textfield(value)
            else:
                logger.info(f"Invalid position field: {key}, unable to set")

    def select_automatic_registration_button(self) -> None:
        '''
        Clicks the Automatic Registration button on the VolumeView Registration window
        '''
        VolumeViewRegFuncs.click_volume_view_automatic_registration_button()

    def accept_inaccurate_registration_warning(self, proceed: bool=True, waitTimeout: int = 2000) -> None:
        '''
        Checks and waits for the Inaccurate Registration warning dialog to appear
        and selects the Yes button to proceed, or No button to cancel

        proceed (bool): True to acknowledge warning and proceed or False to cancel
        waitTimeout (int): Time to wait (in milliseconds) for the Inaccurate registration warning dialog to appear
        '''
        if proceed:
            VolumeViewRegFuncs.click_volume_view_inaccurate_registration_yes_button(waitTimeout)
        else:
            VolumeViewRegFuncs.click_volume_view_inaccurate_registration_no_button(waitTimeout)

    def select_convert_to_correction_button(self) -> None:
        '''
        Clicks the Convert To Correction button on the VolumeView Registration window
        '''
        VolumeViewRegFuncs.click_volume_view_convert_to_correction_button()

    def select_registration_reset_button(self) -> None:
        '''
        Clicks the Reset button on the VolumeView Registration window
        '''
        VolumeViewRegFuncs.click_volume_view_reset_button()

    def select_volume_view_registration_dismiss_button(self) -> None:
        '''
        Clicks the Dismiss button on the VolumeView Registration window
        '''
        VolumeViewRegFuncs.click_volume_view_registration_dismiss_button()

    def select_volume_view_registration_accept_button(self) -> None:
        '''
        Clicks the Accept button on the VolumeView Registration window
        '''
        VolumeViewRegFuncs.click_volume_view_registration_accept_button()

    def edit_comment_and_approve_registration_dialog(self, approval_comment: str) -> None:
        '''
        Checks and waits for the registration approval dialog to appear, enters the
        specified approval comment or initials and clicks the OK button.
        '''
        VolumeViewRegFuncs.edit_volume_view_registration_approval_comment_field(approval_comment)
        VolumeViewRegFuncs.click_volume_view_registration_approval_ok_button()